#!/bin/sh
# layer-2 load audit -- go -- generated by
# Research/data_representation/audit_generate.py . Do not hand-edit; regenerate.
# Every line of /out/l2_go.txt is FACT_ID|RESULT, FACT_ID being
# <form>.<representation>.<probe>.
set -u
ROOT=/work/l2_go
rm -rf "$ROOT"; mkdir -p "$ROOT"
export HOME=/work
export GOFLAGS=-mod=mod
export GO111MODULE=off
export GOCACHE=/work/.gocache
export GOPATH=/work/.gopath
export PATH=/persist/dart-sdk/bin:$PATH

# swift's binaries want an ncurses name the image does not ship under; the fix
# is per-container, so every script that may touch swift re-applies it.
ncurses_fix() {
  if [ -f /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 ]; then
    ln -sf /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 \
       /usr/lib/x86_64-linux-gnu/libncurses.so.6 2>/dev/null
    ldconfig 2>/dev/null
  fi
}
ncurses_fix

OUT=/out/l2_go.txt
: > "$OUT"
echo "=== layer-2 load audit -- go ==="
date -u +%Y-%m-%dT%H:%M:%SZ
if ! command -v go >/dev/null 2>&1; then
  echo "go: TOOLCHAIN ABSENT -- nothing run"
  echo "__ABSENT__|<absent>" >> "$OUT"
  exit 0
fi


# ---- nothing.nil (interface{}).null
D=$ROOT/p1; mkdir -p "$D"; cd "$D"
cat > main.go <<'L2_SRC_EOF'
package main

import "fmt"

func main() {
	var v interface{} = nil;
	fmt.Println("nothing.nil (interface{}).null" + "|" + (fmt.Sprintf("%v", v)))
}
L2_SRC_EOF
V=ok
if ! timeout 180 go build -o prog main.go > build.out 2> build.err; then V="<compile-error>"; fi
if [ "$V" = ok ]; then
  if timeout 30 ./prog > run.out 2> run.err; then :; else
    V="<aborted>"
  fi
  grep -F "nothing.nil (interface{}).null|" run.out >> "$OUT" || V="${V}"
fi
grep -qF "nothing.nil (interface{}).null|" "$OUT" || echo "nothing.nil (interface{}).null|$V" >> "$OUT"

